```js
const BANNED_FLUFF_PATTERNS = [
  /\b(?:seamless|delightful|supercharge|effortless|magic|game-changer|game-changing|revolutionary|frictionless|paradigm-shifting|next-gen|next-generation|synergy|best-in-class|industry-leading|coming soon|placeholder)\b/gi
];

export function auditLexicalHygiene(visibleText, { maxWordsPerSentence = 18, maxJIndex = 0.05 } = {}) {
  const clean = String(visibleText || '').replace(/\s+/g, ' ').trim();
  const sentences = clean.split(/[.!?]+/).map((s) => s.trim()).filter(Boolean);
  const words = clean.split(/\s+/).filter(Boolean);

  const clicheHits = [];
  for (const re of BANNED_FLUFF_PATTERNS) {
    const matches = clean.match(re);
    if (matches) clicheHits.push(...matches.map((m) => m.toLowerCase()));
  }

  const longSentences = sentences
    .map((sentence) => ({ sentence, wordCount: sentence.split(/\s+/).filter(Boolean).length }))
    .filter((entry) => entry.wordCount > maxWordsPerSentence);

  // Detect uppercase 2-6 char acronyms lacking adjacent "(ACRONYM)" first-scan expansion.
  const acronyms = clean.match(/\b[A-Z]{2,6}\b/g) || [];
  const unexpandedAcronyms = acronyms.filter((acr) => !new RegExp(`\\(${acr}\\)`).test(clean));
  const jIndex = words.length > 0 ? unexpandedAcronyms.length / words.length : 0;

  return {
    passed: clicheHits.length === 0 && longSentences.length === 0 && jIndex <= maxJIndex,
    clicheHits: [...new Set(clicheHits)],
    longSentences,
    jIndex: Number(jIndex.toFixed(4)),
    unexpandedAcronyms: [...new Set(unexpandedAcronyms)]
  };
}
```

```js
// Homograph-safe Habitat A jargon validator (zero dependencies).
const UNCONDITIONAL_PLUMBING = [
  'scim', 'sdek', 'rls', 'oscal', 'etag', 'spiffe', 'odata', 'opencost',
  'pkcs11', 'ml-dsa', 'clickhouse', 'debezium', 'zarf', 'tetragon', 'ebpf',
  'oidc', 'saml', 'jwt', 'jsonb', 'fsm', 'postgres', 'postgresql', 'sha-256',
  'ui-ir', 'cryptoshred'
];

function isAmbiguousPlumbingLeak(token, text) {
  if (token === 'worm') {
    return /\bWORM\b/.test(text) ||
      /\bworm[\s_-]+(?:audit|ledger|storage|retention|compliance|log|rules?|immutable)\b/i.test(text) ||
      /\bwrite[- ]once[- ]read[- ]many\b/i.test(text);
  }
  if (token === 'cedar') {
    return /\bCedar\s+(?:policy|policies|ABAC|RBAC|PDP|engine|schema|guard|rules?)\b/i.test(text) ||
      /\bAWS\s+Cedar\b/i.test(text);
  }
  if (token === 'spire') {
    return /\bSPIRE\b/.test(text) ||
      /\bSPIFFE\s*[/&-]\s*SPIRE\b/i.test(text) ||
      /\bspire[\s_-]+(?:agent|server|workload|svid)\b/i.test(text);
  }
  return false;
}

export function lintHabitatACopy(visibleText) {
  const leaks = [];
  for (const token of UNCONDITIONAL_PLUMBING) {
    const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (new RegExp(`\\b${escaped}\\b`, 'i').test(visibleText)) {
      leaks.push(token);
    }
  }
  for (const homograph of ['worm', 'cedar', 'spire']) {
    if (isAmbiguousPlumbingLeak(homograph, visibleText)) {
      leaks.push(homograph);
    }
  }
  return { passed: leaks.length === 0, leaks };
}
```

