      const dl = document.getElementById('cc-anatomy-list');
      dl.replaceChildren(...mod.anatomy.map(([term, desc]) => {
        const wrap = document.createElement('div');
        const dt = document.createElement('dt');
        dt.textContent = term;
        const dd = document.createElement('dd');
        dd.textContent = desc;
        wrap.append(dt, dd);
        return wrap;
      }));
    });
  });
});
